import { runWithRequestContext } from '@pyreon/runtime-server'
import { setCookieSource, useCookie, useStorage } from '@pyreon/storage'
import { AsyncLocalStorage } from 'node:async_hooks'

// server: each concurrent request reads its own Cookie header.
// runWithRequestContext (renderToString does the same) isolates the signal registry per request.
const current = new AsyncLocalStorage<Request>()
setCookieSource(() => current.getStore()?.headers.get('cookie') ?? '')

const handle = <T>(req: Request, render: () => Promise<T>) =>
  current.run(req, () => runWithRequestContext(render))

// shared: the cookie decides the first paint; localStorage mirrors it for fast reads and other tabs
function useTheme() {
  const cookie = useCookie<'light' | 'dark'>('theme', 'light', { maxAge: 60 * 60 * 24 * 365, sameSite: 'lax' })
  const local = useStorage('theme', cookie())
  const set = (next: 'light' | 'dark') => {
    local.set(next)
    cookie.set(next)
  }
  return { theme: local, set }
}

import { useStorage } from '@pyreon/storage'

type Prefs = { theme: 'light' | 'dark'; density: 'cozy' | 'compact' }

const prefs = useStorage<Prefs>('prefs', { theme: 'light', density: 'cozy' }, {
  version: 2,
  // runs on read for a value stored under an older version (or none: from = 0),
  // including one another tab just wrote
  migrate: (old, from) => (from < 2 ? { ...(old as Prefs), density: 'cozy' } : (old as Prefs)),
})

prefs.set({ ...prefs(), theme: 'dark' }) // saved; every open tab updates
